1	import { createServer } from 'node:http';
2	import type { IncomingMessage, ServerResponse } from 'node:http';
3	import { mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from 'node:fs';
4	import { randomUUID } from 'node:crypto';
5	import { join } from 'node:path';
6	
7	const PRODUCT: string = 'QuillPress';
8	const RESOURCE: string = 'articles';
9	const MAX_BODY_BYTES: number = 5 * 1024 * 1024;
10	const PAGE: string = `<!doctype html>
11	<html lang="zh-CN">
12	<meta charset="utf-8">
13	<meta name="viewport" content="width=device-width,initial-scale=1">
14	<title>QuillPress · 内容编辑与刊物发布</title>
15	<style>
16	body{font-family:system-ui,sans-serif;max-width:52rem;margin:3rem auto;padding:0 1rem;line-height:1.7;color:#1f2328}
17	a{color:#175b9c}
18	h2{margin-top:2rem}
19	form{border:1px solid #d0d7de;border-radius:8px;padding:1rem 1.25rem;margin:1rem 0 1.5rem}
20	form.editing{border-color:#175b9c;box-shadow:0 0 0 2px rgba(23,91,156,.15)}
21	label{display:block;font-weight:600;margin:.9rem 0 .3rem}
22	input[type=text],textarea{width:100%;box-sizing:border-box;font:inherit;padding:.5rem .6rem;border:1px solid #d0d7de;border-radius:6px;background:#fff;color:inherit}
23	textarea{resize:vertical}
24	button{margin-top:1.1rem;font:inherit;padding:.5rem 1.3rem;border-radius:6px;border:1px solid #175b9c;background:#175b9c;color:#fff;cursor:pointer}
25	button.secondary{background:#fff;color:#175b9c;margin-left:.6rem}
26	button:disabled{opacity:.55;cursor:default}
27	button.danger{border-color:#c0392b;background:#fff;color:#c0392b}
28	.status{margin:.8rem 0 0;min-height:1.4em}
29	.status.ok{color:#1a7f37}.status.err{color:#c0392b}.status.warn{color:#8a5a00}
30	.edit-banner{margin:0 0 .25rem;padding:.6rem .8rem;border-radius:6px;background:#eef4fb;border:1px solid #b6d2ee;color:#14467a;font-size:.92rem}
31	.edit-banner code{background:#dde9f6;padding:0 .3rem;border-radius:3px}
32	.edit-banner .meta{color:#3d6391;font-size:.85rem;margin-top:.2rem}
33	ul.articles{list-style:none;padding:0;margin:0}
34	article.draft{border:1px solid #d0d7de;border-radius:8px;padding:1rem 1.25rem;margin:1rem 0}
35	article.draft.editing{border-color:#175b9c;box-shadow:0 0 0 2px rgba(23,91,156,.15)}
36	.draft h3{margin:0 0 .4rem;word-break:break-word}
37	.draft .meta{color:#656d76;font-size:.85rem;margin:0 0 .5rem}
38	.draft .summary{white-space:pre-wrap;word-break:break-word;margin:0 0 .4rem;color:#3a4149}
39	.draft .actions{margin:.6rem 0 0}
40	.draft .actions button{margin:0;padding:.3rem .9rem;font-size:.88rem}
41	.draft .editing-tag{margin-left:.5rem;font-size:.78rem;font-weight:600;color:#175b9c;border:1px solid #175b9c;border-radius:999px;padding:0 .55rem;vertical-align:middle}
42	.empty{color:#656d76}
43	.empty.err{color:#c0392b}
44	.conflict{margin-top:1rem;border:1px solid #d9a441;border-radius:8px;background:#fffaf0;padding:1rem 1.25rem}
45	.conflict h3{margin:0 0 .3rem;color:#8a5a00;font-size:1.05rem}
46	.conflict .conflict-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-top:.7rem}
47	@media (max-width:46rem){.conflict .conflict-grid{grid-template-columns:1fr}}
48	.conflict .ver{border:1px solid #d0d7de;border-radius:6px;padding:.7rem .85rem;background:#fff;min-width:0}
49	.conflict .ver.saved{border-color:#8ab46a;background:#f6fbf2}
50	.conflict .ver h4{margin:0 0 .5rem;font-size:.92rem}
51	.conflict .ver dl{margin:0}
52	.conflict .ver dt{font-weight:600;font-size:.82rem;color:#57606a;margin-top:.5rem}
53	.conflict .ver dt:first-child{margin-top:0}
54	.conflict .ver dd{margin:.15rem 0 0;white-space:pre-wrap;word-break:break-word;font-size:.88rem;background:#f6f8fa;border-radius:4px;padding:.35rem .5rem;max-height:12rem;overflow:auto}
55	.conflict .ver.saved dd{background:#eef5e8}
56	.conflict .ver dd.empty-field{color:#8a8f98;font-style:italic;background:transparent;padding:0}
57	.conflict .actions{margin-top:.8rem}
58	.conflict .actions button{margin-top:0}
59	.conflict .actions .tip{font-size:.82rem;color:#8a5a00;margin-left:.6rem}
60	</style>
61	<main>
62	<h1>QuillPress</h1>
63	<p>内容编辑与刊物发布</p>
64	
65	<section aria-labelledby="compose-heading">
66	<h2 id="compose-heading">保存草稿</h2>
67	<form id="draft-form" autocomplete="off">
68	  <div id="edit-banner" class="edit-banner" hidden></div>
69	  <label for="title">标题</label>
70	  <input id="title" name="title" type="text">
71	  <label for="summary">摘要（可选）</label>
72	  <textarea id="summary" name="summary" rows="3"></textarea>
73	  <label for="body">正文</label>
74	  <textarea id="body" name="body" rows="10"></textarea>
75	  <button id="save-btn" type="submit">保存草稿</button>
76	  <button id="cancel-btn" class="secondary" type="button" hidden>取消编辑</button>
77	  <p id="status" class="status" role="status" aria-live="polite"></p>
78	  <div id="conflict-box" class="conflict" hidden></div>
79	</form>
80	</section>
81	
82	<section aria-labelledby="list-heading">
83	<h2 id="list-heading">草稿列表</h2>
84	<ul id="article-list" class="articles"></ul>
85	<p id="empty-tip" class="empty">草稿加载中…</p>
86	</section>
87	
88	<p><a href="/api/articles">查看文章列表接口</a> · <a href="/health">服务状态</a></p>
89	</main>
90	<script>
91	(function () {
92	  'use strict';
93	  var form = document.getElementById('draft-form');
94	  var titleInput = document.getElementById('title');
95	  var summaryInput = document.getElementById('summary');
96	  var bodyInput = document.getElementById('body');
97	  var saveBtn = document.getElementById('save-btn');
98	  var cancelBtn = document.getElementById('cancel-btn');
99	  var statusEl = document.getElementById('status');
100	  var editBanner = document.getElementById('edit-banner');
101	  var conflictBox = document.getElementById('conflict-box');
102	  var listEl = document.getElementById('article-list');
103	  var emptyTip = document.getElementById('empty-tip');
104	  var articles = [];
105	  var saving = false;
106	  // null = 新建草稿模式；对象 = 正在编辑的服务端版本 {id,title,summary,body,version}
107	  var editing = null;
108	
109	  function setStatus(text, kind) {
110	    statusEl.textContent = text || '';
111	    statusEl.className = 'status' + (kind ? ' ' + kind : '');
112	  }
113	  function setEmpty(text, kind) {
114	    emptyTip.textContent = text || '';
115	    emptyTip.className = 'empty' + (kind ? ' ' + kind : '');
116	    emptyTip.hidden = !text;
117	  }
118	  function hideConflict() {
119	    conflictBox.hidden = true;
120	    conflictBox.textContent = '';
121	  }
122	  function formatTime(iso) {
123	    var d = new Date(iso);
124	    return isNaN(d.getTime()) ? String(iso) : d.toLocaleString();
125	  }
126	  function render() {
127	    var sorted = articles.slice().sort(function (a, b) {
128	      var ta = a && a.createdAt ? String(a.createdAt) : '';
129	      var tb = b && b.createdAt ? String(b.createdAt) : '';
130	      if (ta !== tb) return ta < tb ? 1 : -1;
131	      return 0;
132	    });
133	    listEl.textContent = '';
134	    sorted.forEach(function (article) {
135	      var isEditing = editing && editing.id === article.id;
136	      var card = document.createElement('article');
137	      card.className = 'draft' + (isEditing ? ' editing' : '');
138	      var h = document.createElement('h3');
139	      h.textContent = article.title == null ? '' : String(article.title);
140	      if (isEditing) {
141	        var tag = document.createElement('span');
142	        tag.className = 'editing-tag';
143	        tag.textContent = '编辑中';
144	        h.appendChild(tag);
145	      }
146	      var meta = document.createElement('p');
147	      meta.className = 'meta';
148	      meta.textContent = '创建时间：' + formatTime(article.createdAt);
149	      var summary = document.createElement('p');
150	      summary.className = 'summary';
151	      var summaryText = article.summary == null ? '' : String(article.summary);
152	      summary.textContent = summaryText;
153	      card.appendChild(h);
154	      card.appendChild(meta);
155	      if (summaryText) card.appendChild(summary);
156	      var actions = document.createElement('p');
157	      actions.className = 'actions';
158	      var editBtn = document.createElement('button');
159	      editBtn.type = 'button';
160	      editBtn.className = 'secondary';
161	      editBtn.textContent = isEditing ? '正在编辑' : '编辑';
162	      editBtn.disabled = !!isEditing;
163	      editBtn.addEventListener('click', function () { startEdit(article.id); });
164	      actions.appendChild(editBtn);
165	      card.appendChild(actions);
166	      var li = document.createElement('li');
167	      li.appendChild(card);
168	      listEl.appendChild(li);
169	    });
170	    setEmpty(sorted.length === 0 ? '还没有保存的草稿。' : '');
171	  }
172	  function load() {
173	    return fetch('/api/articles', { headers: { accept: 'application/json' } })
174	      .then(function (r) {
175	        if (!r.ok) throw new Error('HTTP ' + r.status);
176	        return r.json();
177	      })
178	      .then(function (data) {
179	        articles = data && Array.isArray(data.articles) ? data.articles : [];
180	        render();
181	      })
182	      .catch(function (err) {
183	        articles = [];
184	        listEl.textContent = '';
185	        setEmpty('草稿列表加载失败：' + (err && err.message ? err.message : err), 'err');
186	      });
187	  }
188	
189	  function setSaving(on, label) {
190	    saving = on;
191	    saveBtn.disabled = on;
192	    saveBtn.textContent = label || (editing ? '保存修改' : '保存草稿');
193	    cancelBtn.disabled = on;
194	  }
195	
196	  function enterCreateMode(message, kind) {
197	    editing = null;
198	    form.reset();
199	    form.classList.remove('editing');
200	    editBanner.hidden = true;
201	    editBanner.textContent = '';
202	    hideConflict();
203	    cancelBtn.hidden = true;
204	    saveBtn.textContent = '保存草稿';
205	    setStatus(message || '', kind || '');
206	    render();
207	  }
208	
209	  function applyEditingState(article) {
210	    editing = {
211	      id: article.id,
212	      title: article.title,
213	      summary: article.summary,
214	      body: article.body,
215	      version: article.version
216	    };
217	    titleInput.value = article.title == null ? '' : String(article.title);
218	    summaryInput.value = article.summary == null ? '' : String(article.summary);
219	    bodyInput.value = article.body == null ? '' : String(article.body);
220	    form.classList.add('editing');
221	    editBanner.innerHTML = '';
222	    var line1 = document.createElement('div');
223	    line1.textContent = '正在编辑草稿：';
224	    var code = document.createElement('code');
225	    code.textContent = String(article.title);
226	    line1.appendChild(code);
227	    var line2 = document.createElement('div');
228	    line2.className = 'meta';
229	    line2.textContent = '创建时间：' + formatTime(article.createdAt) + ' · 标识：' + String(article.id);
230	    editBanner.appendChild(line1);
231	    editBanner.appendChild(line2);
232	    editBanner.hidden = false;
233	    cancelBtn.hidden = false;
234	    saveBtn.textContent = '保存修改';
235	    hideConflict();
236	    setStatus('已载入该草稿当前保存的内容，可以开始修改。', null);
237	    render();
238	    titleInput.focus();
239	  }
240	
241	  function isDirty() {
242	    if (!editing) {
243	      return titleInput.value !== '' || summaryInput.value !== '' || bodyInput.value !== '';
244	    }
245	    return titleInput.value !== editing.title
246	      || summaryInput.value !== editing.summary
247	      || bodyInput.value !== editing.body;
248	  }
249	
250	  function startEdit(id) {
251	    if (saving) return;
252	    if (isDirty() && !window.confirm('当前表单有未保存的修改，打开另一篇草稿将放弃这些输入。确定继续吗？')) {
253	      return;
254	    }
255	    setSaving(true, '读取中…');
256	    setStatus('正在读取草稿内容…', null);
257	    fetch('/api/articles/' + encodeURIComponent(id), { headers: { accept: 'application/json' } })
258	      .then(function (r) {
259	        return r.json().catch(function () { return null; }).then(function (data) {
260	          if (!r.ok || !data || !data.article) {
261	            throw new Error(data && data.error ? data.error : ('HTTP ' + r.status));
262	          }
263	          return data.article;
264	        });
265	      })
266	      .then(function (article) {
267	        setSaving(false);
268	        // 正文必须来自单篇接口，绝不使用列表里的摘要充当正文
269	        applyEditingState(article);
270	      })
271	      .catch(function (err) {
272	        setSaving(false);
273	        saveBtn.textContent = editing ? '保存修改' : '保存草稿';
274	        setStatus('打开草稿失败：' + (err && err.message ? err.message : err) + '，可稍后重试。', 'err');
275	      });
276	  }
277	
278	  cancelBtn.addEventListener('click', function () {
279	    if (saving || !editing) return;
280	    // 取消不提交任何修改，也不删除原文章，直接回到新建草稿状态
281	    if (isDirty() && !window.confirm('取消将放弃当前未保存的修改，原草稿不会被删除。确定取消编辑吗？')) {
282	      return;
283	    }
284	    enterCreateMode('已取消编辑，原草稿未改动。可以新建草稿。', null);
285	  });
286	
287	  function fieldValue(text, isEmpty) {
288	    var dd = document.createElement('dd');
289	    if (isEmpty) {
290	      dd.className = 'empty-field';
291	      dd.textContent = '（空）';
292	    } else {
293	      dd.textContent = text;
294	    }
295	    return dd;
296	  }
297	
298	  function showConflict(saved) {
299	    // 只展示对照，绝不重置表单、绝不自动重试覆盖
300	    conflictBox.textContent = '';
301	    var h = document.createElement('h3');
302	    h.textContent = '检测到较新的已保存内容';
303	    var p = document.createElement('p');
304	    p.textContent = '这篇草稿在其他页面已被修改并保存。为避免覆盖新版本，本次保存已被拒绝。你输入的内容仍保留在上方表单中，可对照右侧最新版本；只有明确放弃当前输入后，才会载入最新内容继续编辑。';
305	    conflictBox.appendChild(h);
306	    conflictBox.appendChild(p);
307	
308	    var grid = document.createElement('div');
309	    grid.className = 'conflict-grid';
310	
311	    var mine = document.createElement('div');
312	    mine.className = 'ver mine';
313	    var mineTitle = document.createElement('h4');
314	    mineTitle.textContent = '你正在编辑的内容（未保存）';
315	    mine.appendChild(mineTitle);
316	    var dl1 = document.createElement('dl');
317	    [['标题', titleInput.value, titleInput.value.trim() === ''],
318	     ['摘要', summaryInput.value, summaryInput.value === ''],
319	     ['正文', bodyInput.value, bodyInput.value === '']].forEach(function (pair) {
320	      var dt = document.createElement('dt');
321	      dt.textContent = pair[0];
322	      dl1.appendChild(dt);
323	      dl1.appendChild(fieldValue(pair[1], pair[2]));
324	    });
325	    mine.appendChild(dl1);
326	
327	    var theirs = document.createElement('div');
328	    theirs.className = 'ver saved';
329	    var tTitle = document.createElement('h4');
330	    tTitle.textContent = '最新已保存内容';
331	    theirs.appendChild(tTitle);
332	    var dl2 = document.createElement('dl');
333	    [['标题', saved.title, saved.title === ''],
334	     ['摘要', saved.summary, saved.summary === ''],
335	     ['正文', saved.body, saved.body === '']].forEach(function (pair) {
336	      var dt = document.createElement('dt');
337	      dt.textContent = pair[0];
338	      dl2.appendChild(dt);
339	      dl2.appendChild(fieldValue(pair[1], pair[2]));
340	    });
341	    theirs.appendChild(dl2);
342	
343	    grid.appendChild(mine);
344	    grid.appendChild(theirs);
345	    conflictBox.appendChild(grid);
346	
347	    var actions = document.createElement('p');
348	    actions.className = 'actions';
349	    var discard = document.createElement('button');
350	    discard.type = 'button';
351	    discard.className = 'danger';
352	    discard.textContent = '放弃当前输入并载入最新内容';
353	    discard.addEventListener('click', function () {
354	      applyEditingState(saved);
355	    });
356	    var keep = document.createElement('button');
357	    keep.type = 'button';
358	    keep.className = 'secondary';
359	    keep.textContent = '保留我的输入，继续修改';
360	    keep.addEventListener('click', function () {
361	      hideConflict();
362	      setStatus('已保留你的输入，请对照后手动调整再保存。', null);
363	      titleInput.focus();
364	    });
365	    var tip = document.createElement('span');
366	    tip.className = 'tip';
367	    tip.textContent = '不会自动覆盖或重置。';
368	    actions.appendChild(discard);
369	    actions.appendChild(keep);
370	    actions.appendChild(tip);
371	    conflictBox.appendChild(actions);
372	    conflictBox.hidden = false;
373	  }
374	
375	  form.addEventListener('submit', function (event) {
376	    event.preventDefault();
377	    if (saving) return;
378	    var trimmedTitle = titleInput.value.trim();
379	    if (!trimmedTitle) {
380	      setStatus('标题不能为空。', 'err');
381	      titleInput.focus();
382	      return;
383	    }
384	    hideConflict();
385	    var isEdit = !!editing;
386	    // 记录本次实际提交的原始字段值，响应返回时据此判断等待期间哪些字段又被编辑过。
387	    var submitted = {
388	      title: titleInput.value,
389	      summary: summaryInput.value,
390	      body: bodyInput.value
391	    };
392	    var payload = {
393	      title: titleInput.value,
394	      summary: summaryInput.value,
395	      body: bodyInput.value
396	    };
397	    var url = '/api/articles';
398	    if (isEdit) {
399	      url += '/' + encodeURIComponent(editing.id);
400	      payload.version = editing.version;
401	    }
402	    setSaving(true, '保存中…');
403	    setStatus(isEdit ? '正在保存修改…' : '正在保存…', null);
404	    fetch(url, {
405	      method: isEdit ? 'PUT' : 'POST',
406	      headers: { 'content-type': 'application/json', accept: 'application/json' },
407	      body: JSON.stringify(payload)
408	    })
409	      .then(function (r) {
410	        return r.json().catch(function () { return null; }).then(function (data) {
411	          return { status: r.status, data: data };
412	        });
413	      })
414	      .then(function (result) {
415	        var data = result.data;
416	        if (result.status === 409 && data && data.article) {
417	          // 版本冲突：保留表单全部输入，展示最新已保存内容供对照。
418	          // 绝不更新本地基准版本——只有用户显式确认载入最新内容后才允许覆盖。
419	          setSaving(false);
420	          saveBtn.textContent = editing ? '保存修改' : '保存草稿';
421	          setStatus('保存被拒绝：存在较新的已保存版本（409）。请对照后选择保留输入或载入最新内容。', 'err');
422	          showConflict(data.article);
423	          return;
424	        }
425	        if (result.status < 200 || result.status >= 300 || !data || !data.article) {
426	          throw new Error(data && data.error ? data.error : ('HTTP ' + result.status));
427	        }
428	        return data.article;
429	      })
430	      .then(function (article) {
431	        if (!article) return; // 冲突分支已处理
432	        if (isEdit) {
433	          var idx = -1;
434	          for (var i = 0; i < articles.length; i++) {
435	            if (articles[i] && articles[i].id === article.id) { idx = i; break; }
436	          }
437	          if (idx >= 0) articles[idx] = article; else articles.push(article);
438	          render();
439	          setSaving(false);
440	          // 保持编辑态：仍是同一篇草稿，可继续修改。
441	          // 成功只确认本次提交的内容；等待响应期间补写的字段原样保留，不被覆盖。
442	          mergeSavedEditingState(article, submitted);
443	        } else {
444	          articles.push(article);
445	          render();
446	          setSaving(false);
447	          enterCreateMode('草稿已保存。可以继续新建草稿。', 'ok');
448	        }
449	      })
450	      .catch(function (err) {
451	        setSaving(false);
452	        saveBtn.textContent = editing ? '保存修改' : '保存草稿';
453	        var prefix = isEdit ? '保存修改失败：' : '保存失败：';
454	        setStatus(prefix + (err && err.message ? err.message : err) + '，输入已保留，可处理后再次操作。', 'err');
455	      });
456	  });
457	
458	  // 保存成功后留在编辑态。成功响应只能确认本次提交的内容：
459	  // 服务端返回的已保存内容成为新的本地基准（version 一并推进，再次保存不会误报冲突），
460	  // 但等待响应期间用户继续输入过的字段必须完整保留当前值（含换行、空行与清空操作），
461	  // 绝不能用刚保存的旧值回填或替换。
462	  function mergeSavedEditingState(article, submitted) {
463	    var savedFields = [
