515	  process.stdout.write(help);
516	  process.exit(args.length === 0 ? 2 : 0);
517	}
518	if (args.shift() !== 'serve') { console.error('Expected serve or --help'); process.exit(2); }
519	let host: string = '127.0.0.1';
520	let port: number = 8080;
521	let dataDir: string = 'data';
522	while (args.length) {
523	  const flag = args.shift();
524	  const value = args.shift();
525	  if (!value || !['--host', '--port', '--data-dir'].includes(flag ?? '')) {
526	    console.error('Each option must be --host, --port or --data-dir followed by a value'); process.exit(2);
527	  }
528	  if (flag === '--host') host = value;
529	  else if (flag === '--port') {
530	    if (!/^\d+$/.test(value) || Number(value) > 65535) { console.error('Port must be between 0 and 65535'); process.exit(2); }
531	    port = Number(value);
532	  } else dataDir = value;
533	}
