638	// Serialize read-modify-write so concurrent saves never lose or corrupt records.
639	let writeQueue: Promise<void> = Promise.resolve();
640	function enqueueWrite<T>(task: () => T): Promise<T> {
641	  const run = writeQueue.then(task);
642	  writeQueue = run.then(() => undefined, () => undefined);
643	  return run;
644	}
645	
646	function readBody(req: IncomingMessage): Promise<string> {
647	  return new Promise((resolve, reject) => {
648	    const chunks: Buffer[] = [];
649	    let size = 0;
650	    let settled = false;
651	    req.on('data', (chunk: unknown) => {
652	      if (settled) return;
653	      const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk));
654	      size += buf.length;
655	      if (size > MAX_BODY_BYTES) {
656	        settled = true;
657	        reject(new HttpError(400, 'request body is too large'));
658	        req.destroy();
659	        return;
660	      }
661	      chunks.push(buf);
662	    });
663	    req.on('end', () => {
664	      if (!settled) resolve(Buffer.concat(chunks).toString('utf8'));
665	    });
666	    req.on('error', (error: Error) => {
667	      if (!settled) reject(new HttpError(400, `could not read request body: ${error.message}`));
668	    });
669	  });
670	}
671	
672	function parseJsonObject(text: string): Record<string, unknown> {
673	  let payload: unknown;
674	  try {
675	    payload = JSON.parse(text);
676	  } catch (error) {
677	    throw new HttpError(400, `invalid JSON: ${(error as Error).message}`);
678	  }
679	  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
680	    throw new HttpError(400, 'request body must be a JSON object');
681	  }
682	  return payload as Record<string, unknown>;
683	}
684	
685	function validateDraftInput(data: Record<string, unknown>): DraftInput {
686	  if (typeof data.title !== 'string') {
687	    throw new HttpError(400, 'title must be a string');
688	  }
689	  const title = data.title.trim();
690	  if (title.length === 0) {
691	    throw new HttpError(400, 'title must not be empty or only whitespace');
692	  }
693	  let summary = '';
694	  if (Object.prototype.hasOwnProperty.call(data, 'summary')) {
695	    if (typeof data.summary !== 'string') throw new HttpError(400, 'summary must be a string when provided');
696	    summary = data.summary;
697	  }
698	  if (typeof data.body !== 'string') {
699	    throw new HttpError(400, 'body must be a string');
700	  }
701	  return { title, summary, body: data.body };
702	}
703	
704	// Updates carry the version the editor loaded; stale versions are rejected.
705	// As with creation, summary may be omitted (saved as empty string) but a
706	// present non-string summary is a 400.
707	function validateUpdateInput(data: Record<string, unknown>): DraftInput & { version: number } {
708	  const fields = validateDraftInput(data);
709	  if (typeof data.version !== 'number' || !Number.isInteger(data.version) || data.version < 0) {
710	    throw new HttpError(400, 'version must be a non-negative integer');
711	  }
712	  return { ...fields, version: data.version };
713	}
