715	async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
716	  let route: string;
717	  try { route = new URL(req.url ?? '/', 'http://localhost').pathname; }
718	  catch { respond(res, 400, { error: 'invalid request path' }); return; }
719	
720	  // /api/articles/:id (match the raw path first; decode only the captured id)
