722	  let itemId: string | null = null;
723	  if (itemMatch) {
724	    try { itemId = decodeURIComponent(itemMatch[1]); }
725	    catch { respond(res, 400, { error: 'invalid article id encoding' }); return; }
726	  }
727	
728	  if (!['/', '/health', '/api/articles'].includes(route) && !itemMatch) {
729	    respond(res, 404, { error: 'not found' });
730	    return;
731	  }
732	
733	  if (route === '/') {
734	    if (req.method === 'GET') { respond(res, 200, PAGE, true); return; }
735	    methodNotAllowed(res, 'GET');
736	    return;
737	  }
738	  if (route === '/health') {
739	    if (req.method === 'GET') { respond(res, 200, { status: 'ok', product: PRODUCT }); return; }
740	    methodNotAllowed(res, 'GET');
741	    return;
742	  }
743	
744	  if (itemMatch && itemId !== null) {
745	    const id = itemId;
746	    if (req.method === 'GET') {
747	      const articles = readArticles();
748	      const article = articles.find((a) => a.id === id);
749	      if (!article) throw new HttpError(404, 'article not found');
750	      respond(res, 200, { article });
751	      return;
752	    }
753	    if (req.method === 'PUT') {
754	      const text = await readBody(req);
755	      const data = parseJsonObject(text);
756	      const fields = validateUpdateInput(data);
757	      const result = await enqueueWrite((): { status: number; article: Article } => {
758	        const records = readArticles();
759	        const index = records.findIndex((a) => a.id === id);
760	        if (index === -1) {
