762	        }
763	        const current = records[index];
764	        if (fields.version !== current.version) {
765	          // 409 carries the currently saved article for side-by-side comparison.
766	          const conflict = new HttpError(409, 'a newer version of this article has been saved');
767	          (conflict as HttpError & { article?: Article }).article = current;
768	          throw conflict;
769	        }
770	        const updated: Article = {
771	          id: current.id,
772	          title: fields.title,
773	          summary: fields.summary,
774	          body: fields.body,
775	          status: current.status,
776	          createdAt: current.createdAt,
777	          version: current.version + 1,
778	        };
779	        records[index] = updated;
780	        writeArticles(records);
781	        return { status: 200, article: updated };
782	      });
783	      respond(res, result.status, { article: result.article });
784	      return;
785	    }
786	    methodNotAllowed(res, 'GET, PUT');
787	    return;
788	  }
789	
790	  // /api/articles
