mkdir -p /tmp/qp-test && cat > /tmp/qp-test/test.js <<'EOF'
const fs = require('fs');
const src = fs.readFileSync('/opt/gsb-production/workspaces/sl-chen/prod-15/A/task005/server.ts','utf8');
const script = src.match(/<script>([\s\S]*?)<\/script>/)[1];

// ---- minimal DOM stub ----
function El(tag) {
  return {
    tag, children: [], textContent: '', className: '', hidden: false,
    disabled: false, value: '', type: '', listeners: {},
    classList: { _s: new Set(), add(c){this._s.add(c);}, remove(c){this._s.delete(c);}, contains(c){return this._s.has(c);} },
    appendChild(c){ this.children.push(c); return c; },
    addEventListener(t, f){ (this.listeners[t] = this.listeners[t]||[]).push(f); },
    querySelector(sel){ if (sel==='code') return this.children.flatMap(function walk(e){return [e, ...e.children.flatMap(walk)];}).find(e=>e.tag==='code')||null; return null; },
    reset(){ els.title.value=''; els.summary.value=''; els.body.value=''; },
    focus(){},
  };
}
const ids = ['draft-form','title','summary','body','save-btn','cancel-btn','status','edit-banner','conflict-box','article-list','empty-tip'];
const els = {};
ids.forEach(id => els[id] = El(id));
// textContent setter should clear children (used by render/banner builders)
function patchTextContent(el) {
  let t = '';
  Object.defineProperty(el, 'textContent', {
    get(){ return t; },
    set(v){ t = String(v); el.children = []; }
  });
}
Object.values(els).forEach(patchTextContent);

const document = {
  getElementById: id => els[id],
  createElement: tag => { const e = El(tag); patchTextContent(e); return e; },
};
const window = { confirm: () => true };

// ---- controllable fetch ----
let pending = [];
const fetchCalls = [];
function fetch(url, opts) {
  opts = opts || {};
  fetchCalls.push({ url, method: opts.method || 'GET', body: opts.body });
  return new Promise(resolve => pending.push({ url, opts, resolve }));
}
function respond(i, status, data) {
  pending[i].resolve({ ok: status>=200&&status<300, status, json: () => Promise.resolve(data) });
  pending.splice(i,1);
}
const flush = () => new Promise(r => setTimeout(r, 0));

function submit(){ els['draft-form'].listeners.submit.forEach(f => f({ preventDefault(){} })); }

(async () => {
  eval(script);
  // initial load
  respond(0, 200, { articles: [] });
  await flush();

  // fill form and submit (create)
  els.title.value = '  第一篇  ';
  els.summary.value = '摘要A';
  els.body.value = '正文一\n\n第二段 <b>不是标记</b>';
  submit();
  if (fetchCalls[1].method !== 'POST') throw new Error('expected POST');
  if (!els['save-btn'].disabled) throw new Error('save btn should be disabled while saving');

  // user keeps typing while waiting
  els.body.value = '正文一\n\n第二段 <b>不是标记</b>\n等待期间补写的一行';
  els.summary.value = ''; // user cleared summary while waiting

  const article = { id:'id-1', title:'第一篇', summary:'摘要A', body:'正文一\n\n第二段 <b>不是标记</b>', status:'draft', createdAt:'2026-10-03T01:00:00.000Z', version:1 };
  respond(0, 201, { article });
  await flush();

  // assertions: user input preserved
  if (els.body.value !== '正文一\n\n第二段 <b>不是标记</b>\n等待期间补写的一行') throw new Error('body overwritten: ' + JSON.stringify(els.body.value));
  if (els.summary.value !== '') throw new Error('cleared summary not preserved: ' + JSON.stringify(els.summary.value));
  if (els.title.value !== '第一篇') throw new Error('untouched title should sync to trimmed saved value, got ' + JSON.stringify(els.title.value));
  // editing state
  if (!els['draft-form'].classList.contains('editing')) throw new Error('form should be in editing state');
  if (els['edit-banner'].hidden) throw new Error('edit banner should be visible');
  if (els['save-btn'].textContent !== '保存修改') throw new Error('button should say 保存修改');
  if (els['cancel-btn'].hidden) throw new Error('cancel btn should be visible');
  if (!/尚未保存/.test(els.status.textContent)) throw new Error('status should mention unsaved changes: ' + els.status.textContent);
  if (!/摘要、正文|正文、摘要/.test(els.status.textContent)) throw new Error('status should name the dirty fields: ' + els.status.textContent);
  // list shows saved content only
  const listJson = JSON.stringify(els['article-list'].children, (k,v) => k==='listeners'||k==='classList'?undefined:v);
  if (listJson.includes('等待期间补写')) throw new Error('list must not show unsubmitted body');
  if (!listJson.includes('摘要A')) throw new Error('list should show saved summary');
  if (!listJson.includes('编辑中')) throw new Error('list card should show editing tag');

  // now user clicks 保存修改 -> must PUT to same id with version 1
  els.summary.value = '更新后的摘要';
  submit();
  const last = fetchCalls[fetchCalls.length-1];
  if (last.method !== 'PUT' || last.url !== '/api/articles/id-1') throw new Error('expected PUT to same article, got ' + last.method + ' ' + last.url);
  const sentBody = JSON.parse(last.body);
  if (sentBody.version !== 1) throw new Error('PUT must base on version from create response');
  if (sentBody.body !== '正文一\n\n第二段 <b>不是标记</b>\n等待期间补写的一行') throw new Error('PUT body must include the typed-during-wait content');
  const updated = { ...article, summary:'更新后的摘要', body: sentBody.body, version:2 };
  respond(0, 200, { article: updated });
  await flush();
  if (!/修改已保存/.test(els.status.textContent)) throw new Error('expected edit-saved status, got: ' + els.status.textContent);

  // scenario 2: clean create (no typing while waiting) -> form cleared
  els['cancel-btn'].listeners.click.forEach(f => f()); // cancel edit back to create mode
  await flush();
  els.title.value = '第二篇'; els.summary.value=''; els.body.value='正文';
  submit();
  const article2 = { id:'id-2', title:'第二篇', summary:'', body:'正文', status:'draft', createdAt:'2026-10-03T02:00:00.000Z', version:1 };
  respond(0, 201, { article: article2 });
  await flush();
  if (els.title.value !== '' || els.body.value !== '') throw new Error('clean create should clear the form');
  if (els['draft-form'].classList.contains('editing')) throw new Error('clean create should not enter editing state');
  if (!/草稿已保存/.test(els.status.textContent)) throw new Error('expected saved status');

  // scenario 3: user types then restores to saved value while waiting -> clean path
  els.title.value = '第三篇'; els.body.value = 'abc';
  submit();
  els.body.value = 'abc typed'; els.body.value = 'abc'; // restored
  const article3 = { id:'id-3', title:'第三篇', summary:'', body:'abc', status:'draft', createdAt:'2026-10-03T03:00:00.000Z', version:1 };
  respond(0, 201, { article: article3 });
  await flush();
  if (els.title.value !== '' || els.body.value !== '') throw new Error('restored-to-saved create should clear the form');

  // scenario 4: create failure keeps input
  els.title.value = '失败篇'; els.body.value = '内容';
  submit();
  respond(0, 500, { error: 'unable to save articles: disk full' });
  await flush();
  if (els.title.value !== '失败篇' || els.body.value !== '内容') throw new Error('failed create must keep input');
  if (els['draft-form'].classList.contains('editing')) throw new Error('failed create must not enter editing state');
  if (!/保存失败/.test(els.status.textContent)) throw new Error('expected failure status');
  if (els['save-btn'].disabled) throw new Error('save btn should be re-enabled after failure');

  console.log('ALL FRONT-END SCENARIOS PASS');
})().catch(e => { console.error('FAIL:', e.message); process.exit(1); });
EOF
